import {html, nothing} from 'lit';
import {msg, str} from '@lit/localize';
import {customElement, state} from 'lit/decorators.js';
import {AIUXWidgetElement, decorators} from '@servicenow/aiux-components-core';
import {createGraphQLClient} from '@servicenow/aiux-components-record';

const {category, discoverable} = decorators;

// Fields needed — sys_view_count is a stats field not present in any form
// view, so we can't use aiux-record-provider/FormAPI here. We fetch with the
// karuna-native GraphQLClient (handles auth/CSRF) instead, matching seismic's
// knowledgeQuery approach.
const KB_QUERY = `
  query($sysId: String!) {
    GlideRecord_Query {
      {{table}}(sys_id: $sysId) {
        _results {
          text          { value }
          sys_updated_on { displayValue }
          sys_view_count { displayValue }
        }
      }
    }
  }
`;

const SNIPPET_MAX = 280;
const SAFE_TABLE_NAME = /^[a-zA-Z_][a-zA-Z0-9_]*$/;

function toSnippet(value, max = SNIPPET_MAX) {
  if (!value) return '';
  // Output is bound via Lit text interpolation (not unsafeHTML), so any
  // residual markup is escaped automatically — no sanitizer needed.
  const text = String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > max ? `${text.slice(0, max).trimEnd()}…` : text;
}

const gql = createGraphQLClient();

/**
 * Knowledge article activity renderer for playbook cards (SDK-built widget).
 *
 * Shows a short excerpt of the article body and the updated/views footer.
 * Title and action buttons are provided by the playbook card / DA layer.
 *
 * Uses karuna's GraphQLClient (from @servicenow/aiux-components-record, kept
 * external) to fetch specific KB fields that are not part of any form view
 * (notably sys_view_count). This matches the seismic knowledgeQuery pattern.
 *
 * Activity props (host-assigned, each a {value} object):
 *   - knowledge_table  : table name (e.g. "kb_knowledge")
 *   - knowledge_record : sys_id of the KB article
 *
 * @element playbook-knowledge-article
 */
@discoverable(true)
@category('platform')
@customElement('playbook-knowledge-article')
export default class PlaybookKnowledgeArticle extends AIUXWidgetElement {
  static ssr = false;

  static properties = {
    knowledge_table: {type: Object},
    knowledge_record: {type: Object}
  };

  @state() _snippet = null;
  @state() _updated = '';
  @state() _views = '';
  @state() _loading = true;
  @state() _error = false;

  _lastFetchKey = '';

  updated() {
    const table = this.knowledge_table?.value;
    const sysId = this.knowledge_record?.value;
    const key = `${table}:${sysId}`;
    if (!table || !sysId || key === this._lastFetchKey) return;
    this._lastFetchKey = key;
    this._fetch(table, sysId);
  }

  async _fetch(table, sysId) {
    this._loading = true;
    this._error = false;
    try {
      if (!SAFE_TABLE_NAME.test(table)) {
        this._error = true;
        return;
      }
      const query = KB_QUERY.replace('{{table}}', table);
      const {data, errors} = await gql.query(query, {sysId});
      if (errors?.length) throw new Error(errors[0].message);

      const result = data?.GlideRecord_Query?.[table]?._results?.[0];
      if (!result) {
        this._error = true;
        return;
      }
      this._snippet = toSnippet(result.text?.value ?? '');
      this._updated = result.sys_updated_on?.displayValue ?? '';
      this._views = result.sys_view_count?.displayValue ?? '';
    } catch {
      this._error = true;
    } finally {
      this._loading = false;
    }
  }

  render() {
    if (!this.knowledge_table?.value || !this.knowledge_record?.value) {
      return html`<p class="text-sm text-base-content/40 italic" role="status">
        ${msg('No knowledge article available.')}
      </p>`;
    }
    if (this._loading) {
      return html`<p class="text-sm text-base-content/40 italic" role="status">
        ${msg('Loading…')}
      </p>`;
    }
    if (this._error) {
      return html`<p class="text-sm text-error" role="alert">
        ${msg('Could not load the knowledge article.')}
      </p>`;
    }

    const {_snippet: snippet, _updated: updated, _views: views} = this;

    return html`
      <div class="flex flex-col gap-2">
        ${snippet
          ? html`<p class="text-sm text-base-content/80 leading-relaxed">${snippet}</p>`
          : nothing}
        ${updated || views
          ? html`<p class="text-xs text-base-content/50">
              ${msg(str`Updated ${updated} · ${views} views`)}
            </p>`
          : nothing}
      </div>
    `;
  }
}
